    /* ---- SIGNING ON THE PAPER (J-1, owner-asked 29 Aug 2026) ----
       A spot is a place on the contract that asks for a mark. The words are
       deliberately plain: "place" rather than "field", because a contract is
       not a form, and "still need you" rather than "incomplete", because the
       reader is being told what is owed and by whom. */
    ct_spot_signature: 'Signature',
    ct_spot_initials: 'Initials',
    ct_spot_fill: 'Sign here',
    ct_spot_replace: 'Change this mark',
    ct_spot_theirs: 'This one is for the other side to fill',
    ct_spot_not_yours: 'That place belongs to somebody else',
    /* A CLAUSE HAS TO EXIST BEFORE A MARK CAN POINT AT IT. A template draft
       nobody has edited has no working text and therefore no addressable
       clause, and a mark anchored to nothing would move the first time the
       wording did. */
    ct_spot_no_anchor: 'This document has no clause to attach a signature to yet — open it in the negotiation once and try again',
