    // ---- settings: design, backup, notifications and email ----
    set_design_sub: 'Det standardutseende varje avtal bär när det publiceras, delas eller exporteras — en <b>struktur</b> (hur sidan är disponerad) och en <b>stil</b> (hur den är klädd), plus din logotyp och din färg. Ett avtals formuleringar och klausulnummer ändras aldrig; bara presentationen gör det. Undertecknade avtal behåller det utseende de förseglades med.',
