    set_notif_sub: 'En förhandling följs här, inte i din inkorg. När en motpart öppnar ett avtal, svarar på en av dina ändringar eller föreslår en egen, landar det på avtalet i HaTi medan du tittar på det — inget mejl skickas, och inget behövs.',
    set_still_emailed: 'Du får fortfarande mejl på slutet',
    set_three_events: 'Tre händelser når din inkorg, eftersom var och en avslutar bevakningen i stället för att fortsätta den: de är <b>redo att underteckna</b>, de har <b>undertecknat</b>, eller de har <b>avböjt</b>. Själva undertecknandet — förfrågan, engångskoden, kedjan av motparters underskrifter — går med e-post som det alltid gjort, eftersom mottagaren inte har något konto här.',
    set_sidebar_sub: 'HaTi håller sidomenyn kort så länge beståndet är litet — Insikter dyker upp av sig själv vid fem avtal. Det här visar alla ytor direkt i stället:',
    set_activation_sub: 'De fyra ögonblick som förutsäger om en arbetsyta blir kvar — första avtalet in, första Copilot-genomgången, första utskicket, första underskriften tillbaka — observerade av servern när de sker (demoexempel räknas inte). Ledstjärnan: <b>första utskicket inom 7 dagar</b>.',
    set_email_sub: 'Delningslänkar till avtal, aviseringar om motpartens svar, påminnelser om oöppnade delningar (efter 3 dagar), förnyelsepåminnelser (90/60/30 dagar i förväg), teaminbjudningar, lösenordsåterställningar och signeringskoder till motparter skickas med e-post. Sätt en <span style="font-family:var(--font-mono)">RESEND_API_KEY</span> på servern för att slå på verklig leverans — till dess visas meddelanden (och engångskoder) i utkorgen nedan för test.',
