/* ---------- which language, and who decides ----------
   Reads through the signed-in user first, so a person carries their language
   between browsers rather than per laptop; the local key is the fallback and
   the only store a signed-out page or a share link has. Mirrors how jxId()
   reads the org record before localStorage, for the same reason. */
function langId() {
  try {
    const me = (typeof currentUser === 'function' && currentUser()) || null;
    if (me && me.lang && STRINGS[me.lang]) return me.lang;
  } catch (e) {}
  try {
    const v = (typeof lsGet === 'function' && lsGet(I18N_LS)) || null;
    if (v && STRINGS[v]) return v;
  } catch (e) {}
  /* Nothing chosen yet: take the language that goes with the workspace's
     market, so a Swedish workspace opens in Swedish rather than making every
     new colleague find the setting. */
  try {
    if (typeof jxId === 'function') {
      const m = jxId();
      const hit = LANGUAGES.find(l => l.market === m);
      if (hit && STRINGS[hit.id]) return hit.id;
    }
  } catch (e) {}
  return I18N_DEFAULT;
}
/* ============================================================
   THE LOCALE FOR A DATE THAT WILL BE READ AS WORDS
   ============================================================
   Owner-reported, 13 Aug 2026: in English mode, a Copilot chart came back with
   "aug. 2026 · sep. 2026 · okt. 2026 · maj 2027". Every date on every screen was
   formatted through jxLocale() — the MARKET's locale — so a Swedish workspace
   printed Swedish month names to a reader who had chosen English.

   That is this file's own distinction, applied to dates for the first time.
   LANGUAGE is the person's and decides the WORDS. MARKET is the company's and
   decides the CONVENTIONS — which currency, and the order a date is written in.
   Both are true at once, so the tag carries both: the reader's language with
   the market's region. An English reader in a Swedish workspace gets
   "13 Aug 2026" — English words, day first, which is what Sweden writes — and
   never the American "Aug 13, 2026" that a bare "en" would give them.

   WHAT THIS IS NOT FOR:
     · NUMBERS. Money and counts stay on jxLocale(). The grouping of SEK belongs
       to the market that spends it, not to the language it is described in.
     · THE CONTRACT. Paper never passes through here — fmtDocDate writes its
       dates from DOC_MONTHS, a fixed list, because the document's words are the
       customer's and are never translated. That rule is unchanged and this
       function must never be pointed at it.

   Memoised on (language, region) rather than computed once: the object-literal
   trap this file warns about is a value frozen at LOAD time, and either half of
   this pair can move while the app is open. */
let _langLocaleAt = null;
function langLocale(){
  const lang = langId() || I18N_DEFAULT;
  let region = '';
  try {
    if (typeof jxLocale === 'function') region = String(jxLocale() || '').split('-')[1] || '';
  } catch (e) {}
  const key = lang + '|' + region;
  if (_langLocaleAt && _langLocaleAt.key === key) return _langLocaleAt.tag;
  let tag = region ? lang + '-' + region : lang;
  /* A malformed tag THROWS inside toLocaleDateString rather than falling back,
     which would take out whichever screen asked. The language alone always
     resolves. */
  try { new Intl.DateTimeFormat(tag); } catch (e) { tag = lang; }
  _langLocaleAt = { key, tag };
  return tag;
}
const langList = () => LANGUAGES.slice();
const langIs = id => langId() === id;
const langName = id => (LANGUAGES.find(l => l.id === id) || {}).name || id;
/* How to name this language TO A MODEL. Used when building a prompt, and when
   rendering a saved answer in whatever language it was originally written in. */
const langPromptName = id => {
  const l = LANGUAGES.find(x => x.id === (id || langId()));
  return l ? `${l.enName} (${l.id})` : String(id || langId());
};

/* ---------- the accessor ----------
   Three levels: this language → English → the key itself. The last is a
   developer seeing their own typo, never a blank button. */
function t(key, vars) {
  const lang = langId();
  const table = STRINGS[lang] || STRINGS[I18N_DEFAULT];
  let s = table[key];
  if (s == null) s = STRINGS[I18N_DEFAULT][key];
  if (s == null) return key;
  return vars ? interpolate(s, vars) : s;
}
/* A count-aware lookup: t('x_one'/'x_other'). Falls back to the bare key so a
   string that never needed a plural still works through the same call. */
function tn(key, n, vars) {
  const v = Object.assign({ n }, vars || {});
  const table = STRINGS[langId()] || STRINGS[I18N_DEFAULT];
  const en = STRINGS[I18N_DEFAULT];
  const suffix = Number(n) === 1 ? '_one' : '_other';
  if (table[key + suffix] != null || en[key + suffix] != null) return t(key + suffix, v);
  return t(key, v);
}
function interpolate(s, vars) {
  return String(s).replace(/\{(\w+)\}/g, (m, k) =>
    (vars[k] == null ? m : String(vars[k])));
}
/* Does this language have every key English has? Used by the parity test and
   by nothing else — a gap is a build-time problem, not a runtime one. */
function langMissingKeys(id) {
  const en = Object.keys(STRINGS[I18N_DEFAULT]);
  const has = STRINGS[id] || {};
  return en.filter(k => has[k] == null);
}

/* ---------- changing it ---------- */
function langSet(id, opts) {
  if (!STRINGS[id]) return false;
  try { if (typeof lsSet === 'function') lsSet(I18N_LS, id); } catch (e) {}
  /* On the USER record where there is one, and on the server — the half that
     matters for email, which the server writes and which cannot see a browser
     setting. Fire-and-forget: the local write above already took effect and
     bootstrap serves the stored value back from now on. */
  try {
    const me = (typeof currentUser === 'function' && currentUser()) || null;
    if (me) {
      me.lang = id;
      if (typeof REMOTE !== 'undefined' && REMOTE && REMOTE.me) REMOTE.me.lang = id;
    }
  } catch (e) {}
  try {
    if (typeof window !== 'undefined' && typeof window.API_MODE === 'function' && window.API_MODE()
      && typeof window.api === 'function')
      window.api('me/lang', 'PUT', { lang: id }).catch(() => {});
  } catch (e) {}
  applyLanguage(opts);
  return true;
}

/* ---------- painting it onto the page ----------
   Static markup carries data-i18n (text), data-i18n-title (the tooltip) and
   data-i18n-ph (a placeholder). Everything else on screen is drawn by JS and
   goes through t() at render time instead — which is most of this app. */
function applyLanguage(opts) {
  const o = opts || {};
  try { document.documentElement.lang = langId(); } catch (e) {}

  try {
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const v = t(el.getAttribute('data-i18n'));
      if (v == null) return;
      /* textContent unless the string genuinely carries markup. Assigning
         innerHTML where a plain label would do is how a translated string
         becomes an injection surface. */
      if (/<[a-z][\s\S]*>/i.test(v)) { try { el.innerHTML = v; } catch (e) { el.textContent = v.replace(/<[^>]+>/g, ''); } }
      else el.textContent = v;
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
      el.setAttribute('title', t(el.getAttribute('data-i18n-title')));
    });
    document.querySelectorAll('[data-i18n-ph]').forEach(el => {
      el.setAttribute('placeholder', t(el.getAttribute('data-i18n-ph')));
    });
    /* An aria-label is read aloud, so it is chrome like any other and has to
       follow the reader. It is also the ONLY label on the icon-only buttons in
       the header, which is exactly the case a screen-reader user cannot work
       around by looking at the picture. */
    document.querySelectorAll('[data-i18n-aria]').forEach(el => {
      el.setAttribute('aria-label', t(el.getAttribute('data-i18n-aria')));
    });
  } catch (e) {}

  /* THE SCREEN YOU ARE ON REDRAWS, so the change is visible immediately rather
     than at the next navigation — EXCEPT while something is being edited.
     Redrawing the negotiation workbench mid-edit would take away unsaved text
     or a live selection, and a language switch is never worth losing work
     over; the new language lands when the edit ends. */
  if (o.repaint === false) return true;
  if (langEditingNow()) return true;
  try { if (typeof window.onLanguageChange === 'function') window.onLanguageChange(); } catch (e) {}
  return true;
}

/* Is the user mid-edit right now? A focused editor or input, or a live text
   selection inside the document surface (which is how a proposal is started). */
function langEditingNow() {
  try {
    const a = document.activeElement;
    if (a && (a.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName || ''))) return true;
    const sel = window.getSelection && window.getSelection();
    if (sel && !sel.isCollapsed && sel.rangeCount) {
      const n = sel.getRangeAt(0).commonAncestorContainer;
      const el = n && (n.nodeType === 1 ? n : n.parentElement);
      if (el && el.closest && el.closest('.hati-doc, [contenteditable="true"]')) return true;
    }
  } catch (e) {}
  return false;
}

/* ---- THE NAME THE RENDERERS CALL IT BY ----
   `t` is the obvious name for a translator and the wrong one for THIS codebase:
   `t` is also its most common loop variable — `list.map(t => …)` over templates,
   contracts and tabs appears in almost every view. Inside one of those, a call
   to t('some_key') resolves to the loop item and not to this function, and the
   failure is silent until something renders. The renderers therefore call it
   i18t / i18tn, which nothing else is ever named. `t` and `tn` stay exported
   for the console and for anything written by hand outside a map. */

/* ---------- THE SERVER SPEAKS ONE LANGUAGE, AND THE SCREEN SPEAKS THE READER'S ----------

   The server answers a refusal with a plain English sentence — 184 distinct
   ones — and js/api.js turns it into an Error whose message is printed
   verbatim, half the time glued to a TRANSLATED prefix. So a Swedish reader who
   tried to save a signed contract met "Det gick inte att spara: This contract
   has been executed and sealed." That is worse than an untranslated screen: a
   sentence in two languages reads as a rendering fault.

   WHERE THE FIX GOES IS THE WHOLE POINT. It is not on the server — a message
   answers a REQUEST, and the server has no reliable business knowing which
   human is looking at the reply (a share link has no account at all). It is not
   at each of the ~200 call sites either. It is at the ONE place a server
   sentence becomes an Error: api(). One lookup there, and every caller
   inherits it.

   WHAT IS TRANSLATED, and it is a decision rather than a budget: the ~40
   sentences a NORMAL USER MEETS in ordinary use — signing in, changing a
   password, saving, sharing, signing, being refused by a permission, uploading
   a file, and every refusal on the counterparty's own page, which is the one
   screen in this product a reader outside the company ever sees. What is
   deliberately left is the developer-shaped validation the interface cannot
   reach ("values must be an object of field_key → value"): translating those
   would be work nobody can check, on sentences nobody sees.

   AN UNKNOWN SENTENCE FALLS THROUGH UNCHANGED, which is what makes this safe to
   extend one message at a time and impossible to break by adding a message on
   the server. */
const SRV_MSG = {
  /* signing in, and the account */
  'Email or password is incorrect': 'srv_bad_credentials',
  'Not signed in': 'srv_not_signed_in',
  'Sign in again': 'srv_sign_in_again',
  'Session expired — please sign in again': 'srv_session_expired',
  'Sign in again — the code window has closed': 'srv_code_window_closed',
  'Your current password is incorrect': 'srv_current_password_wrong',
  'Password must be at least 8 characters': 'srv_password_min',
  'Choose a password you have not used here before': 'srv_password_reused',
  'Set your own password before making changes': 'srv_set_own_password_first',
  'That code is not right': 'srv_code_wrong',
  'That code is not right — check the app and try again': 'srv_code_wrong_app',
  'Code expired — request a new one': 'srv_code_expired',
  'Request a code first': 'srv_request_code_first',
  'A current code — or an unused recovery code — is needed to turn this off': 'srv_two_step_off_needs_code',
  /* permissions */
  'Admin access required': 'srv_admin_required',
  'Admin or Editor access required': 'srv_admin_or_editor_required',
  'A Viewer cannot approve a contract.': 'srv_viewer_cannot_approve',
  'A Viewer cannot rule on a change.': 'srv_viewer_cannot_rule',
  'A viewer cannot rule on a review': 'srv_viewer_cannot_review',
  'You do not have access to that value stream': 'srv_no_stream_access',
  'You cannot change your own role': 'srv_not_own_role',
  'You cannot change your own access': 'srv_not_own_access',
  'You cannot remove yourself': 'srv_not_remove_self',
  'Nobody reviews their own work.': 'srv_no_self_review',
  'Nobody oversees their own contracts.': 'srv_no_self_oversee',
  'Only the person who asked can withdraw it': 'srv_only_asker_withdraws',
  /* saving and the record */
  'Contract not found': 'srv_contract_not_found',
  'This contract has been executed and sealed': 'srv_executed_sealed',
  'This contract is executed — its record can no longer change': 'srv_executed_no_change',
  'Somebody has already signed this contract, so the signing route cannot be changed.': 'srv_route_locked',
  'A contract cannot be filed under itself.': 'srv_no_self_parent',
  'Nothing to change': 'srv_nothing_to_change',
  'The contract record could not be read': 'srv_record_unreadable',
  /* sharing and signing */
  'Share link not found or expired': 'srv_share_gone',
  'This share link is no longer active': 'srv_share_inactive',
  'This link was revoked': 'srv_link_revoked',
  'A response was already submitted for this link': 'srv_already_answered',
  'A valid recipient email is required to send by email': 'srv_recipient_email_required',
  'A work email is required to sign': 'srv_work_email_required',
  'Email verification required before signing': 'srv_verify_before_signing',
  'There is nothing to send': 'srv_nothing_to_send',
  'This contract is no longer available': 'srv_contract_gone',
  'This contract is no longer available. Ask the sender for an up-to-date copy.': 'srv_contract_gone_ask',
  'This contract is no longer available — your response could not be recorded. Contact the sender.': 'srv_contract_gone_response_lost',
  'The signing route on this contract was changed and this link no longer belongs to it. Ask the sender for a fresh signing link.': 'srv_route_moved',
  'The link this reading copy was created from is no longer active, so this copy has closed with it.': 'srv_parent_link_closed',
  'This link cannot carry a discussion': 'srv_no_discussion_here',
  'Only a durable link can be refreshed — create a new share instead': 'srv_not_durable',
  /* files */
  'That is not a Word (.docx) or PDF file — the converter reads those two kinds': 'srv_not_docx_or_pdf',
  'That PDF is password-protected. Remove the password and upload it again, or upload the Word version.': 'srv_pdf_locked',
  'That PDF could not be read — it may be damaged. Try re-saving it, or upload the Word version.': 'srv_pdf_damaged',
  'No readable text found in the document': 'srv_no_readable_text',
  'The file could not be decoded': 'srv_file_undecodable',
  /* Copilot */
  'Copilot engine not configured': 'srv_no_copilot_key',
  'Copilot returned no structured result': 'srv_copilot_no_result',
  /* people */
  'A member with that email already exists': 'srv_member_email_taken',
  'A valid email is required': 'srv_valid_email_required',
  'Enter a valid work email address — it is your sign-in and your password-reset route': 'srv_work_email_explained',
  'Your full name is required': 'srv_full_name_required',
  'That colleague is not a member of this workspace': 'srv_not_a_member',
  'That person is not a member of this workspace.': 'srv_not_a_member',
  'That reviewer is not a member of this workspace.': 'srv_reviewer_not_a_member',
};
/* Sentences that carry a detail after them. The PREFIX is translated and the
   detail — a provider's own words, a file name — is kept verbatim, because it
   is the half that says what to do next and it is not ours to rewrite. */
const SRV_MSG_PREFIX = [
  ['Copilot request failed: ', 'srv_copilot_failed'],
  ['Copilot provider error (', 'srv_copilot_provider'],
  ['OCR request failed: ', 'srv_ocr_failed'],
  ['The monthly report could not be sent: ', 'srv_monthly_failed'],
];
function srvMsg(msg) {
  const raw = String(msg == null ? '' : msg);
  if (!raw) return raw;
  const key = SRV_MSG[raw];
  if (key) return t(key);
  for (const [pre, k] of SRV_MSG_PREFIX) {
    if (raw.startsWith(pre)) return t(k) + raw.slice(pre.length);
  }
  return raw;   /* unknown sentences pass through untouched — see the note above */
}
const i18t = t, i18tn = tn;

const I18N_API = { STRINGS, LANGUAGES, I18N_DEFAULT, I18N_LS,
  t, tn, i18t, i18tn, srvMsg, langId, langSet, langList, langIs, langName, langPromptName, langLocale,
  langMissingKeys, applyLanguage, langEditingNow };
/* Two hosts, one dictionary: the browser gets globals like every other module,
   and server/server.js requires this file so an email can be written in the
   recipient's language from the same table the screens use. */
if (typeof window !== 'undefined') Object.assign(window, I18N_API);
if (typeof module !== 'undefined' && module.exports) module.exports = I18N_API;
